#include <algorithm>
#include <cassert>
#include <functional>
#include <iostream>
#include <set>
#include <string>
#include <vector>
using namespace std;
// 각 조각은 후보보다 짧아야 하므로 후보 자신 한 번을 답으로 세지 않습니다.
bool composite(const string&target,const set<string>&dict){
 vector<bool> reach(target.size()+1,false);reach[0]=true;
 for(size_t start=0;start<target.size();++start){
  if(!reach[start])continue;
  for(const string&word:dict){
   if(word.empty()||word.size()>=target.size()||word.size()>target.size()-start)continue;
   if(target.compare(start,word.size(),word)==0)reach[start+word.size()]=true;
  }
 }
 return reach[target.size()];
}
string longestComposite(const vector<string>&words){
 set<string>dict(words.begin(),words.end());dict.erase("");
 string best;
 for(const string&word:dict)if(composite(word,dict)){
  if(word.size()>best.size()||(word.size()==best.size()&&word<best))best=word;
 }
 return best;
}
// 후보를 자르는 모든 경계를 직접 탐색하는 독립 기준입니다.
bool reference(const string&s,const set<string>&dict,size_t pos,int pieces){
 if(pos==s.size())return pieces>=2;
 for(size_t end=pos+1;end<=s.size();++end)
  if(dict.count(s.substr(pos,end-pos))&&reference(s,dict,end,pieces+1))return true;
 return false;
}
int main(){
 const vector<string>pool={"a","b","aa","ab","ba","bb","aba"};size_t cases=0;
 for(unsigned mask=0;mask<(1U<<pool.size());++mask){
  vector<string>w;set<string>d;
  for(size_t i=0;i<pool.size();++i)if(mask&(1U<<i)){w.push_back(pool[i]);d.insert(pool[i]);}
  string best;
  for(const string&s:d)if(reference(s,d,0,0))if(s.size()>best.size()||(s.size()==best.size()&&s<best))best=s;
  assert(longestComposite(w)==best);++cases;
 }
 assert(longestComposite({"rain","bow","rainbow","rainbowrain","stone"})=="rainbowrain");
 assert(longestComposite({"a","ba","ababa","babab","b"})=="ababa");
 assert(longestComposite({"stone","stone"}).empty());
 cout<<cases<<" dictionary cases + reuse/tie/duplicate cases passed\n";
}
